<style>
:root{--bg:#080d17;--side:#0b111e;--card:#0e1625;--line:rgba(152,177,220,.14);--text:#edf3ff;--muted:#91a1bb;--blue:#4a8aff;--cyan:#5be3ed;--green:#80e0b5;--amber:#f3c879}*{box-sizing:border-box}body{margin:0;background:var(--bg);color:var(--text);font:14px 'DM Sans',sans-serif;min-height:100vh}a{color:inherit;text-decoration:none}button,input,select,textarea{font:inherit}.app{min-height:100vh;display:grid;grid-template-columns:236px minmax(0,1fr)}.sidebar{background:var(--side);border-right:1px solid var(--line);padding:23px 14px;display:flex;flex-direction:column}.brand{display:flex;align-items:center;gap:10px;padding:0 9px 28px;font:700 17px 'Space Grotesk',sans-serif;letter-spacing:.13em}.mark{width:30px;height:34px;color:var(--cyan)}.brand small{display:block;font:500 8px 'DM Sans',sans-serif;letter-spacing:.15em;color:#7e91b1;margin-top:1px}.navlabel{padding:13px 11px 8px;color:#5f718f;font-size:9px;font-weight:700;letter-spacing:.15em;text-transform:uppercase}.navitem{display:flex;align-items:center;gap:12px;padding:11px;border-radius:10px;color:#8e9fba;margin:2px 0;font-size:12px}.navitem.active{background:rgba(65,127,255,.14);border:1px solid rgba(65,127,255,.17);color:#dfeaff}.navitem svg{width:17px;height:17px}.bottom{margin-top:auto}.profile{border-top:1px solid var(--line);padding:17px 8px 0;display:flex;align-items:center;gap:10px}.avatar{width:34px;height:34px;display:grid;place-items:center;border-radius:11px;background:linear-gradient(135deg,#2859a9,#15314e);color:#d9f7ff;font-weight:700}.profile b{font-size:11px;display:block}.profile span{font-size:10px;color:var(--muted)}.main{min-width:0}.top{height:69px;display:flex;align-items:center;justify-content:space-between;padding:0 32px;border-bottom:1px solid var(--line);background:rgba(8,13,23,.8)}.crumb{font-size:11px;color:#8293ae}.crumb b{color:#e8efff}.right{display:flex;align-items:center;gap:12px}.pill{display:inline-flex;align-items:center;gap:7px;padding:7px 10px;border-radius:8px;color:#8fe0