@media(max-width:1050px){.app{grid-template-columns:205px minmax(0,1fr)}.content{padding:25px 22px}.top{padding:0 22px}.stats{grid-template-columns:repeat(2,minmax(0,1fr))}}
@media(max-width:650px){.app{display:block}.sidebar{display:none}.top{height:59px;padding:0 15px}.mobile-brand{display:flex;align-items:center;gap:8px;font:700 14px 'Space Grotesk',sans-serif;letter-spacing:.1em}.mobile-brand svg{width:23px;height:27px;color:var(--cyan)}.crumb{display:none}.content{padding:22px 14px 35px}.pagehead{flex-direction:column}.pagehead h1{font-size:26px}.pagehead .btn{width:100%}.stats{gap:9px}.stat{padding:12px}.value{font-size:23px}.stat-top{font-size:9px}.fields{grid-template-columns:1fr}.field.full{grid-column:auto}.panel{padding:14px}.right .pill{display:none}}
